python3 - <<'PY'
p='elvis.config'
s=open(p).read()
# elvis 5 drops the {elvis, [{config, [...]}]} wrapper: top level is a proplist
# whose `config' key holds the list of directory maps.
s = s.replace("""[
    {elvis, [
        {config, [""", """[
    {config, [""")
s = s.replace("""        ]}
    ]}
].""", """    ]}
].""")
# de-indent the map bodies by 4 spaces
lines = s.split('\n')
out = []
started = False
for ln in lines:
    if ln.startswith('    {config, ['):
        started = True
        out.append(ln); continue
    if started and ln.startswith('        '):
        out.append(ln[4:])
    else:
        out.append(ln)
s = '\n'.join(out)
s = s.replace("%% Rule names track elvis_core 4.x. Several rules were renamed in 4.0",
              "%% Rule names track elvis_core 5.x. Several rules were renamed in 4.0")
open(p,'w').write(s)
PY
head -20 elvis.config; echo "..."; tail -8 elvis.config

